  const record = { date: '2026-02-03', category: 'not-a-real-category', amount: 5 };
  // normalizeCategory maps unknown strings to 'other', which does have a rule.
  assert.strictEqual(signedAmount(record), 5);
});

test('matches the bank statement for the shipped transactions.csv fixture', () => {
  const csv = fs.readFileSync(path.join(__dirname, '..', 'data', 'transactions.csv'), 'utf8');
  const report = buildReport(parseCsv(csv));
  assert.strictEqual(report.net, 180.9);
});

